        headers: { "X-Lab-Key": key, "Content-Type": "application/json" },
      },
      (res) => {
        const chunks = [];
        res.on("data", (c) => chunks.push(c));
        res.on("end", () => {
          try {
            resolve({
              status: res.statusCode,
              body: JSON.parse(Buffer.concat(chunks).toString() || "null"),
            });
          } catch {
            reject(new Error("Invalid backend response"));
          }
        });
      },
    );
